CREATE TABLE v29361 (v29362 VARCHAR(255) NOT NULL, v29363 VARCHAR(255) NOT NULL) AS SELECT EXTRACTVALUE(@xml, '/a/@b[contains(.,"1")]'), ST_ASTEXT(ST_ENVELOPE(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(LINESTRING(0 0,0 10,10 10),GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(), point(4 4), GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())))'))), REGEXP_INSTR('a', 'a', 1, 0, 0, NULL), AES_DECRYPT(NULL, 'x'), EXTRACTVALUE('<a>A<b>B1</b><b>B2</b></a>', '/a/b[count(.)]'), TIMEDIFF(CAST('00:00:00.0' AS TIME), CAST('00:00:00' AS TIME)), PERIOD_DIFF(-1.1E-37, 'MULTIPOINT(5 11,5 15)')